import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"頤","description":"焦氏易林注 - 頤","frontmatter":{"title":"頤","description":"焦氏易林注 - 頤"},"headers":[],"relativePath":"zh/classics/jiaoyilin/027.md","filePath":"zh/classics/jiaoyilin/027.md"}'),l={name:"zh/classics/jiaoyilin/027.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="頤" tabindex="-1">頤 <a class="header-anchor" href="#頤" aria-label="Permalink to “頤”">​</a></h1><h3 id="頤-1" tabindex="-1">頤 <a class="header-anchor" href="#頤-1" aria-label="Permalink to “頤”">​</a></h3><h3 id="頤之乾" tabindex="-1">頤之乾 <a class="header-anchor" href="#頤之乾" aria-label="Permalink to “頤之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>思初道古，哀吟無輔。陽明不制，上失其所。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>乾為初、為古，《頤》互坤為思、為哀，震為道、為吟，一陽在上故曰失所。陽明不制者，言陽不能制陰也。全用遇卦象。○道，元本作悼，依宋本、汲古。</p><h3 id="頤之坤" tabindex="-1">頤之坤 <a class="header-anchor" href="#頤之坤" aria-label="Permalink to “頤之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>江河淮海，天之奧府。眾利所聚，可以饒有，樂我君子。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《觀》。</p><h3 id="頤之屯" tabindex="-1">頤之屯 <a class="header-anchor" href="#頤之屯" aria-label="Permalink to “頤之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>三雁俱行，避暑就涼。適與矰遇，為繳所傷。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>震為雁，數三，故曰三雁。坎為寒，離伏，故曰避暑就涼。伏巽為矰繳，兌為傷。○矰，元本作繒，依宋本、汲古。行，汲古作飛，依宋元本。</p><h3 id="頤之蒙" tabindex="-1">頤之蒙 <a class="header-anchor" href="#頤之蒙" aria-label="Permalink to “頤之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>秋南春北，隨時休息。處和履中，安無憂凶。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>伏兌為秋，艮納丙，故曰秋南。震為春，坤為北，故曰春北。艮為鴻雁，雁隨陽轉故曰隨時。艮為時、為休息。坎為中和，震為履，艮為安。</p><h3 id="頤之需" tabindex="-1">頤之需 <a class="header-anchor" href="#頤之需" aria-label="Permalink to “頤之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>履危無患，跳脫獨全。不利出門，傷我左膝。疾病不食，鬼哭其室。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>坎為危、為患，跳脫在外故無患。乾為門戶，出門遇險故不利。兌為傷膝象，疑為坎股之屈信全在膝，而坎為矯輮，又為美脊，以義、以形皆有膝象。互離為東，故曰傷我左膝。坎為病，兌為食，坎憂，故雲不食。坎為鬼、為室，兌為口，故曰鬼哭其室也。○跳，汲古作逃，依宋元本。膝，宋元本作踝，今依汲古。</p><h3 id="頤之訟" tabindex="-1">頤之訟 <a class="header-anchor" href="#頤之訟" aria-label="Permalink to “頤之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>東家凶婦，怨其公姥。毀柈破盆，棄其飯飡，使吾困貧。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>巽為婦，坎凶，伏震為東、為公，巽為姥。姥，母也。伏震為柈、為盆，坎為破，巽為飯飡，風散故曰棄。伏坤為吾、為貧。○怨，元本作怒，姥作姑，依宋本、汲古。柈，汲古作盤，依宋元本。</p><h3 id="頤之師" tabindex="-1">頤之師 <a class="header-anchor" href="#頤之師" aria-label="Permalink to “頤之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>泥滓污辱，棄捐溝瀆。眾所笑哭，終不顯錄。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坤土坎水故曰泥、曰污，坎為溝瀆、為眾，震為笑哭，坤賤坎隱，故曰終不顯錄。○污，宋元本作洿，依汲古。</p><h3 id="頤之比" tabindex="-1">頤之比 <a class="header-anchor" href="#頤之比" aria-label="Permalink to “頤之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>旦往暮還，各與相存，身無凶患。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>《頤》震為旦、為往，坤為暮，艮者，震之反，故曰暮還。坤為身，坎為患。○凶患，汲古作患凶，依宋元本。</p><h3 id="頤之小畜" tabindex="-1">頤之小畜 <a class="header-anchor" href="#頤之小畜" aria-label="Permalink to “頤之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>六翮長翼，夜過射國。高飛冥冥，羿氏無得。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>伏《豫》。震為翮、為翼，坎數六，故曰六翮長翼。坤為夜、為國，震為射，故曰射國。震為飛，坤惡，故曰羿，坤虛故無得。</p><h3 id="頤之履" tabindex="-1">頤之履 <a class="header-anchor" href="#頤之履" aria-label="Permalink to “頤之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>蜂蠆之門，難以止息。嘉媚之士，為王所食。從去其室。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>巽為蟲，伏坎為毒，故曰蜂蠆。乾為門，風散故難以止息。兌為媚、為食，乾為王，伏坎為室，言王食養嘉士，士皆歸王室也。伏震為士。○門，汲古作國，今依宋元本。</p><h3 id="頤之泰" tabindex="-1">頤之泰 <a class="header-anchor" href="#頤之泰" aria-label="Permalink to “頤之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>被狐乘龍，為王道東。過時不返，使我憂聾。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>伏艮為狐，震為龍，言被狐裘乘龍馬也。震為道、為東，乾為王，震往故不返。坤為憂，坤迷故聾。○被，宋元本作放，依汲古。</p><h3 id="頤之否" tabindex="-1">頤之否 <a class="header-anchor" href="#頤之否" aria-label="Permalink to “頤之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>雹梅零墜，心思憒憒，亂我魂氣。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>乾艮皆為果，而乾為冰，故曰雹梅。《方言》：&quot;大褲謂之倒頓&quot;，郭註：即今之雹褲。雹褲、雹梅皆象形語，巽隕故曰墜。坤為心，坤迷故曰憒憒。○汲古多&quot;懷憂少愧&quot;四字，在第三句，依宋元本。按：乾為魂，坤為亂，故曰亂我魂氣。</p><h3 id="頤之同人" tabindex="-1">頤之同人 <a class="header-anchor" href="#頤之同人" aria-label="Permalink to “頤之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>長女三嫁，進退無羞。牝狐作妖，夜行離憂。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>巽為長女，伏震為嫁，數三，故曰三嫁。巽為進退，坤為羞，坤伏故無羞。伏坎為狐、為妖、為夜、為憂，巽為牝。○無羞，各本皆作多態，依《觀》之《蠱》校。</p><h3 id="頤之大有" tabindex="-1">頤之大有 <a class="header-anchor" href="#頤之大有" aria-label="Permalink to “頤之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>轟轟，馳東逐西。盛盈必毀，高位崩顛。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦象。震為車、為聲，故曰轟。震為東、為馳逐，兌為西。乾為盛盈，兌為毀，故曰盛盈必毀。艮為高位，艮覆為震，故曰崩顛。○第二句宋元本作驅車東西，茲依汲古。</p><h3 id="頤之謙" tabindex="-1">頤之謙 <a class="header-anchor" href="#頤之謙" aria-label="Permalink to “頤之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>乘船涉濟，載水逢火。賴得無患，蒙我生全。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>震為船，坎為水、為濟，艮為火，故曰載水逢火。坎為患，震為樂，故曰無患。○生全，汲古作全生，依宋元本。</p><h3 id="頤之豫" tabindex="-1">頤之豫 <a class="header-anchor" href="#頤之豫" aria-label="Permalink to “頤之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>至德之君，政仁且溫。伊呂股肱，國富民安。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為君、為仁，坤為政，艮為火，故曰政仁且溫。伏巽為股肱，伊吾，語聲。呂，從口，皆震象也。又艮為臣，亦或為艮象，坤為國、為民。○至德，汲古作德至，依宋元本。</p><h3 id="頤之隨" tabindex="-1">頤之隨 <a class="header-anchor" href="#頤之隨" aria-label="Permalink to “頤之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>生不逢時，困且多憂。無有冬夏，心常悲愁。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震為生，艮為時，兌向晦，故生不逢時。艮為困，巽為憂，正反巽，故多憂。震春兌秋，故曰無有冬夏，言無時不悲愁也。</p><h3 id="頤之蠱" tabindex="-1">頤之蠱 <a class="header-anchor" href="#頤之蠱" aria-label="Permalink to “頤之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>南歷玉山，東入生門。登福上堂，飲萬歲漿。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>震為南、為玉，艮山，故曰南歷王山。艮門，震東，巽入，故東入生門。震為登、為福，艮為堂，故曰登福上堂。兌口為飲，兌澤故曰漿，震為萬歲。</p><h3 id="頤之臨" tabindex="-1">頤之臨 <a class="header-anchor" href="#頤之臨" aria-label="Permalink to “頤之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>大斧斫木，讒人敗國。東關二五，禍及三子。晉人亂危，懷公出走。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>兌為斧，震為木，兌震為口、為言，故曰讒人。坤為國、為關，兌數十，故曰二五。《左傳僖二十八年》：&quot;姬賂外嬖梁五與東關嬖五&quot;是也。震數三，故曰三子，申生、夷吾、重耳也。震為晉、為人、為公，坤為禍亂、為心，故曰懷公。○斫，宋元本作破，依汲古。</p><h3 id="頤之觀" tabindex="-1">頤之觀 <a class="header-anchor" href="#頤之觀" aria-label="Permalink to “頤之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>一室百孫，公悅嫗歡。相與笑言，家樂以安。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>艮為室、為孫，坤為百，故曰一室百孫。巽為嫗，伏震為公、為歡笑，艮為家。</p><h3 id="頤之噬嗑" tabindex="-1">頤之噬嗑 <a class="header-anchor" href="#頤之噬嗑" aria-label="Permalink to “頤之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>隨陽轉行，不失其常。君安於鄉，國無咎殃。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>離為日，震為隨、為行、為轉運，而離上震下，故曰隨陽轉行。震為君，艮為鄉、為國，艮止，故君安而國無殃咎也。</p><h3 id="頤之賁" tabindex="-1">頤之賁 <a class="header-anchor" href="#頤之賁" aria-label="Permalink to “頤之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>群虎入邑，求索肉食。大人御守，君不失國。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>艮為虎、為邑，正覆艮，故曰群虎。艮為求，坎為肉，故求索肉食。震為大人、為君，艮為守、為國，能守故不失也。</p><h3 id="頤之剝" tabindex="-1">頤之剝 <a class="header-anchor" href="#頤之剝" aria-label="Permalink to “頤之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>弱足刖跟，不利出門。商賈無贏，折崩為患。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>湯火之憂，轉解喜來。此用《頤》象。震為足、為跟，艮刀，故曰刖，坤柔，故曰弱，故出不利，坤為門也。震為商賈，上震覆故無贏、故崩折。坤為患、為水，艮火故曰湯火。○商，宋元本作市，崩作朋，皆非，依汲古。</p><h3 id="頤之復" tabindex="-1">頤之復 <a class="header-anchor" href="#頤之復" aria-label="Permalink to “頤之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>夏台羑里，湯文卮處。鬼侯飲食，岐人悅喜。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《頤》象，義詳前《無妄》林。《史記》：&quot;西伯、九侯為紂三公，紂烹九侯&quot;，徐廣曰，九一作鬼。○首二句依《無妄》校。羑里，各本皆作幽戶，湯文作文君。</p><h3 id="頤之無妄" tabindex="-1">頤之無妄 <a class="header-anchor" href="#頤之無妄" aria-label="Permalink to “頤之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>棟橈榱壞，廊屋大敗。宮闕空廓，如冬枯樹。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為榱棟，巽隕落故橈壞。艮為廊屋、為宮闕，巽隕故大敗，震虛故空廓。乾為冬，震為樹，巽為枯。○空廓，宋元本作空廊，茲依汲古。</p><h3 id="頤之大畜" tabindex="-1">頤之大畜 <a class="header-anchor" href="#頤之大畜" aria-label="Permalink to “頤之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>讒以內安，不利其國。室家大懼，幽囚重閉。疾病多求，罪亂憒憒。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>三至上正反震，故曰讒。艮為國、為室家，伏坤為懼、為幽閉、為重、為疾病、為罪亂，言內有讒人，群臣被讒，幽囚重閉，不利其國也。坤迷故曰憒憒。○讒，宋元本作說，利作離，大懼作相歡，均依汲古。</p><h3 id="頤之頤" tabindex="-1">頤之頤 <a class="header-anchor" href="#頤之頤" aria-label="Permalink to “頤之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>家給人足，頌聲並作。四夷賓服，乾戈捲閣。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>艮為家，震為人，坤多故給足。震為聲。坤陰，故為夷狄，震卦數四，故曰四夷。震為賓，艮為乾戈，艮止故捲閣。</p><h3 id="頤之大過" tabindex="-1">頤之大過 <a class="header-anchor" href="#頤之大過" aria-label="Permalink to “頤之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>六龍俱怒，戰於阪下。蒼黃不勝，旅人艱苦。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>乾數六，故曰六龍。震為怒，《頤》正反震，故曰戰。艮為阪，坤為下，震為蒼黃、為旅人。皆用伏象。○阪，汲古作陂，蒼作倉，均依宋元本。</p><h3 id="頤之坎" tabindex="-1">頤之坎 <a class="header-anchor" href="#頤之坎" aria-label="Permalink to “頤之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>天下雷行，塵起不明。市空無羊，疾人憂凶。三木不辜，脫歸家邦。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>艮為天，震為雷，艮上震下，故曰天下雷行。艮為塵，坎黑故不明。兌為羊，巽為市，兌巽皆伏，故曰市空無羊。坎為疾、為憂，震為木，數三，故曰三木。三木，拲、桎、梏，亦坎象也。艮為家邦，震為脫，三木不辜，言雖被三木之刑而非其罪也。</p><h3 id="頤之離" tabindex="-1">頤之離 <a class="header-anchor" href="#頤之離" aria-label="Permalink to “頤之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>一指食肉，口無所得。染其鼎鼐，舌饞於腹。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>伏《坎》。艮為指，坎為肉，兌為口，震為鼎，鼎兌為舌，離為腹。《左傳》：&quot;子公染指於鼎，嘗之而出&quot;，林似指其事。一當作以。</p><h3 id="頤之咸" tabindex="-1">頤之咸 <a class="header-anchor" href="#頤之咸" aria-label="Permalink to “頤之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>喜笑不常，失其福慶。口闢言疥，行者畏忌。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>兌為喜笑，正反兌故曰不常。乾為福慶，巽隕落故曰失。兌為口，乾為言，闢，邪也，疥，瘡也，言口邪言穢也。伏坤為畏忌，艮為節，故曰疥。○闢，汲古作辨，依宋元本。疥，宋元本作，依汲古。</p><h3 id="頤之恒" tabindex="-1">頤之恒 <a class="header-anchor" href="#頤之恒" aria-label="Permalink to “頤之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>毛生豪背，國樂民富。侯王有德。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>《山海經》：竹山有獸，狀如豚，白毛，名曰豪彘。註：夾髀有麄毫，能以脊上毫射物，故曰毛生豪背。震為毛，伏艮為背、為國，坤為民、為富，乾為侯王。○豪，汲古作毫，依宋元本。</p><h3 id="頤之遯" tabindex="-1">頤之遯 <a class="header-anchor" href="#頤之遯" aria-label="Permalink to “頤之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>豶豕童牛，害傷不來。三女同堂，生我福仁。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>巽為豕，艮為牛，艮少，故曰豶豕童牛，象本《大畜》也。互巽為女，艮數三，艮為堂，故曰三女同堂。乾為福仁。伏震為生。○害，宋元本作童，依汲古。女，汲古作光，依宋元本。</p><h3 id="頤之大壯" tabindex="-1">頤之大壯 <a class="header-anchor" href="#頤之大壯" aria-label="Permalink to “頤之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>江海淮濟，盈溢為害。邑被其瀨，年困無歲。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>乾為河、為盈，兌毀故曰害。伏坤為邑，乾為年歲。○濟，宋元本作海，依汲古。</p><h3 id="頤之晉" tabindex="-1">頤之晉 <a class="header-anchor" href="#頤之晉" aria-label="Permalink to “頤之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>兩虎爭鬬，股創無處。不成仇讎，行解卻去。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>詳《大畜》之《損》。</p><h3 id="頤之明夷" tabindex="-1">頤之明夷 <a class="header-anchor" href="#頤之明夷" aria-label="Permalink to “頤之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>五嶽四瀆，潤洽為德。行不失理，民賴恩福。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為山，坎為五，故曰五嶽。震卦數四，坤坎皆為水，故曰四瀆、曰潤洽。《淮南子》：&quot;河潤百裡&quot;。坤為理、為民。○潤，元本作，依宋本、汲古。</p><h3 id="頤之家人" tabindex="-1">頤之家人 <a class="header-anchor" href="#頤之家人" aria-label="Permalink to “頤之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>載車乘馬，南逢君子。與我嘉福，雖憂無咎。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用《頤》象。震為車、為馬、為載、為乘、為南，艮為君子，故曰南逢君子。震為嘉福，坤為憂。○福，宋元本作喜，依汲古。</p><h3 id="頤之睽" tabindex="-1">頤之睽 <a class="header-anchor" href="#頤之睽" aria-label="Permalink to “頤之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>缺囊破筐，空無黍粱。不媚如公，棄於糞牆。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>此用《頤》象。坤為囊，震為筐，伏兌毀，故曰缺、曰破。震為稻粱、為黍稷，坤虛故曰空。震為公，兌為媚，兌伏故曰不媚。艮為牆，坤柔，故曰糞牆。○粱，元本作稷，依汲古。</p><h3 id="頤之蹇" tabindex="-1">頤之蹇 <a class="header-anchor" href="#頤之蹇" aria-label="Permalink to “頤之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>殺行桃園，見虎東還。螳螂之敵，使我無患。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此用《頤》象。震為行、為桃，艮為園、為虎，震為東、為反，故曰東還螳螂，疑伏兌象。《左傳宣二年》：&quot;趙穿攻靈公於桃園，●之&quot;，《淮南子》：&quot;齊莊公出行，有螳螂奮臂當車，回車避之&quot;。○還，元本作西，使作仁，均依汲古。</p><h3 id="頤之解" tabindex="-1">頤之解 <a class="header-anchor" href="#頤之解" aria-label="Permalink to “頤之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>箕仁入室，政衰弊極。抱其彞器，奔於他國，因禍受福。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>此用《頤》象。震為箕、為仁，艮為室，入室謂箕子囚於圜室也。坤為政、為弊，艮為抱，震為彞器、為奔，坤為國。抱其彞器，《周本紀》：&quot;少師強抱其祭器以犇周&quot;，《宋世家》又雲：&quot;微子持祭器造於軍門&quot;是也。○箕仁，元本作飢人，依宋本、汲古。黃丕烈從元本，非，因不知入室之義，而據《殷本紀》&quot;西伯伐飢國&quot;為說，然於下文義愈不協。</p><h3 id="頤之損" tabindex="-1">頤之損 <a class="header-anchor" href="#頤之損" aria-label="Permalink to “頤之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>庭燎夜明，追古傷今。陽弱不制，陰雄坐戾。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《大有》。</p><h3 id="頤之益" tabindex="-1">頤之益 <a class="header-anchor" href="#頤之益" aria-label="Permalink to “頤之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>懸貆素餐，食非其任。失輿剝廬，休坐徙居。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《震》。○貆，宋元本作狟，徙作從，茲依汲古。</p><h3 id="頤之夬" tabindex="-1">頤之夬 <a class="header-anchor" href="#頤之夬" aria-label="Permalink to “頤之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>嘉門福喜，繒帛盛熾。日就為得，財寶敵國。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>乾為門、為福，兌悅故喜。伏坤為繒帛，乾為盛、為日、為財寶，伏坤為多，故曰敵國，言富可敵國。○喜，宋元本作善，依汲古。</p><h3 id="頤之姤" tabindex="-1">頤之姤 <a class="header-anchor" href="#頤之姤" aria-label="Permalink to “頤之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>執綏登車，驂乘東游。說齊解燕，霸國以安。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>《史記蘇秦傳》：&quot;臣居燕不能使燕重，而在齊則燕重&quot;，林用其事。巽為綏，伏震為車、為東、為燕、為解，巽為齊，伏坤為國，乾健故目［當作曰］霸國。</p><h3 id="頤之萃" tabindex="-1">頤之萃 <a class="header-anchor" href="#頤之萃" aria-label="Permalink to “頤之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>水深無桴，蹇難何游。商伯失利，庶人愁憂。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>坤為水，震為桴，震伏故無桴，艮止故蹇。巽為利，坤喪故失利。坤為庶人、為憂。</p><h3 id="頤之升" tabindex="-1">頤之升 <a class="header-anchor" href="#頤之升" aria-label="Permalink to “頤之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>三鳥鴛鴦，相隨俱行。南到饒澤，食魚與粱。君子長樂，見惡不傷。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為鳥，數三，故曰三鳥，坤文故曰鴛鴦。震為隨、為行、為南，兌為澤，坤多，故曰饒澤。坤為魚，震為粱，互兌，故曰食魚與粱。伏艮為君子，坤為惡，震樂，故見惡不傷。○長樂，宋元本作樂長，依汲古。</p><h3 id="頤之革" tabindex="-1">頤之革 <a class="header-anchor" href="#頤之革" aria-label="Permalink to “頤之革”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>言無要約，不成券契。殷叔季姬，公孫爭之。強人委禽，不悅於心。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>正反兌相背故曰言無要約，不成券契。《左傳昭元年》：&quot;鄭徐吾犯之妹美，公孫楚聘之矣，公孫黑強委禽焉&quot;。伏震為姬、為公，艮為季孫，正反艮故曰爭。艮為禽，兌悅，伏坎為心。○殷叔未詳，或徐吾犯出自殷。</p><h3 id="頤之鼎" tabindex="-1">頤之鼎 <a class="header-anchor" href="#頤之鼎" aria-label="Permalink to “頤之鼎”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>牛馬聾聵，不知聲味。遠賢賤仁，自令亂憒。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>伏《屯》。坤牛、震馬、坎耳，坤迷，故聾瞶。震為聲，本卦巽為味，震為賢仁，在下故曰遠賢賤仁。坤為賤、為亂。○各本下有&quot;疾病無患，生福在門&quot;八字，語意與上文不協，斷為衍文，依《小過》之《謙》刪。瞶，汲古作憒，依宋元本。令，宋元本作合，依汲古。</p><h3 id="頤之震" tabindex="-1">頤之震 <a class="header-anchor" href="#頤之震" aria-label="Permalink to “頤之震”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>從商進游，飽食無憂。囹圄之困，中子見囚。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>震為商、為游、為食，坎中滿故飽食。坎為憂，震樂故無。坎為囹圄、為中男，艮止故見囚。○飽食，汲古作食飽，依宋元本。</p><h3 id="頤之艮" tabindex="-1">頤之艮 <a class="header-anchor" href="#頤之艮" aria-label="Permalink to “頤之艮”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>據鬥運樞，順天無憂，與樂並居。艮為星，卦數七，故曰鬥。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>互坎為樞，艮為天，坤順，卦二陰承一陽，故曰順天坎憂。震樂故曰並居。</p><h3 id="頤之漸" tabindex="-1">頤之漸 <a class="header-anchor" href="#頤之漸" aria-label="Permalink to “頤之漸”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>姬奭薑望，為武守邦。屏藩燕齊，周室以強，子孫億昌。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>伏震為姬、為奭，巽為薑，離為望，故曰姬奭薑望。震為武，艮為守、為邦、為屏藩，艮為燕，巽齊，言姬奭封燕，薑望封齊，屏藩周室，為武王守上也。震周坎室，震子艮孫。億，大也。</p><h3 id="頤之歸妹" tabindex="-1">頤之歸妹 <a class="header-anchor" href="#頤之歸妹" aria-label="Permalink to “頤之歸妹”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>亡羊東澤，循堤直北。子思其母，復返其所。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>兌為羊、為澤，震東故曰東澤，震往故曰亡羊。坎為北，震為阪，故曰循堤直北。震為子，坎為思，巽為母，巽伏故思母。震為歸，故復返其所。○復，汲古作隨，依宋元本。</p><h3 id="頤之豐" tabindex="-1">頤之豐 <a class="header-anchor" href="#頤之豐" aria-label="Permalink to “頤之豐”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>張目關口，舌直距齒。然諾不行，政亂無緒。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>離為目，震為張，兌口伏艮，故曰關口。兌為舌、為齒，二至五正反兌相背故曰距。距，抗也。相背，故然諾不行。巽為緒，二至五正反巽，故亂而無緒。此皆用覆象，自覆象失傳，《困》&quot;有言不信&quot;等詞皆失解。○關，汲古作開，依宋元本。</p><h3 id="頤之旅" tabindex="-1">頤之旅 <a class="header-anchor" href="#頤之旅" aria-label="Permalink to “頤之旅”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>載船逢火，憂不為禍。家在山東，入門見公。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>通《節》。震為船，艮為火，故曰載船逢火。坎為憂、為禍，船近水故雖逢火不為禍患。艮為家、為山，震為東，故曰家在山東。震為公，艮為門，巽入，故曰入門見公。</p><h3 id="頤之巽" tabindex="-1">頤之巽 <a class="header-anchor" href="#頤之巽" aria-label="Permalink to “頤之巽”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>絕國異路，心不相慕。蛇子兩角，使我相惡。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>通《震》。艮為國、為路，坎為心、為慕，二至上兩震相反，故不相慕。巽為蛇，伏艮為角，兌卦數二，故曰兩角。《新序》：&quot;孫叔敖為兒時，出游，見兩頭蛇殺而埋之，歸而泣&quot;，林似指其事。○國，宋元本作言，依汲古。</p><h3 id="頤之兌" tabindex="-1">頤之兌 <a class="header-anchor" href="#頤之兌" aria-label="Permalink to “頤之兌”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>鼻頂移徙，居不安坐。枯竹復生，失其寵榮。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>伏艮為鼻、為頂，互震故曰移徙。艮為居、為坐，震動故不安坐。震為竹，離科上槁，故曰枯竹。震為復、為生，艮陽在上為寵榮，互坎故失其寵榮。坎為失也。○頂，汲古作項，復作後，依宋元本。居，宋元本作君，依汲古。</p><h3 id="頤之渙" tabindex="-1">頤之渙 <a class="header-anchor" href="#頤之渙" aria-label="Permalink to “頤之渙”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>火息無光，年歲不長，殷商以亡。艮火在坎水上故無光。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>震為年歲、為子，故曰殷商。子，殷姓也，坎失故曰亡。○殷商以亡，汲古作殷湯遠明，元本作殷湯光明，而首句多殷商以亡一句。按：殷湯以亡，即殷湯遠明，元本誤為上句耳，宋本與汲古皆作三句可證。又年字汲古作千，依宋元本。</p><h3 id="頤之節" tabindex="-1">頤之節 <a class="header-anchor" href="#頤之節" aria-label="Permalink to “頤之節”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>文王四乳，仁愛篤厚。子畜十男，夭折無有。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>震為王，伏離，故曰文王。艮為乳，震卦數四，故曰四乳。震為仁愛，艮為篤厚，震為子，兌數十，故曰十男。兌為折，震生故不折。《帝王世紀》：&quot;文王身長十尺有四乳&quot;，《詩》：&quot;大姒嗣徽音，則百斯男&quot;，《傳》：&quot;太姒十子&quot;，據《史記索隱》註十子&quot;伯邑考、武王、管、蔡、霍、魯、衛、毛、聃、曹&quot;是也。○夭，元本作發，音跋，《周禮》有赤犮氏，註：赤犮，猶捇拔除去之也，亦可通，茲依宋本、汲古，惟各本皆作無有夭折，依《鼎》之《蒙》校，有厚為韻。</p><h3 id="頤之中孚" tabindex="-1">頤之中孚 <a class="header-anchor" href="#頤之中孚" aria-label="Permalink to “頤之中孚”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>熊羆豹狼，在山陰陽。伺鹿取獐，道畏難。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>二至五正反艮故曰熊羆豹狼。艮納丙故曰山陽，艮反則山陰矣，故曰山陰。易《中孚》：&quot;鳴鶴在陰&quot;，亦山陰也，解者皆誤。艮止故曰伺，艮手故曰取。震鹿艮麞。，斥也，掌檢行道路伺候盜賊。○，汲古作伏，非，依宋元本。</p><h3 id="頤之小過" tabindex="-1">頤之小過 <a class="header-anchor" href="#頤之小過" aria-label="Permalink to “頤之小過”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>凋葉被霜，獨蔽不傷。駕入喜門，與福為婚。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為葉，巽落故曰凋葉。艮為門，震為喜福，霜或用兌澤象，抑或取大坎。○凋，宋本、汲古作雕，依元本。</p><h3 id="頤之既濟" tabindex="-1">頤之既濟 <a class="header-anchor" href="#頤之既濟" aria-label="Permalink to “頤之既濟”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>黃離白日，照我四國。元首昭明，民賴恩福。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>《離九二》：曰&quot;黃離&quot;。離為日、為照。艮為國。震卦數四。故曰四國。艮為首，坤為民，頤本大離，林詞全取《頤》象。○恩，從宋元本，汲古作為。</p><h3 id="頤之未濟" tabindex="-1">頤之未濟 <a class="header-anchor" href="#頤之未濟" aria-label="Permalink to “頤之未濟”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>順風直北，與歡相得。歲熟年豐，邑無盜賊。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>似亦取《頤》象。</p>',312)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
